export function solve(emails: string[]): string[] {
  const GOOGLE_DOMAINS = new Set(['gmail.com', 'googlemail.com']);
  const PLUS_ONLY_DOMAINS = new Set(['outlook.com', 'hotmail.com', 'live.com']);

  const stripPlusSuffix = (local: string): string => {
    const plus = local.indexOf('+');
    return plus >= 0 ? local.slice(0, plus) : local;
  };

  // Removes single dots; keeps any run of two or more dots unchanged.
  const removeSingleDots = (local: string): string =>
    local.replace(/\.+/g, (run) => (run.length >= 2 ? run : ''));

  const canonicalize = (raw: string): string => {
    const email = raw.toLowerCase();
    const at = email.lastIndexOf('@');
    if (at < 0) {
      return email;
    }

    let local = email.slice(0, at);
    let domain = email.slice(at + 1);

    if (GOOGLE_DOMAINS.has(domain)) {
      local = removeSingleDots(stripPlusSuffix(local));
      domain = 'gmail.com';
    } else if (PLUS_ONLY_DOMAINS.has(domain)) {
      local = stripPlusSuffix(local);
    }

    return `${local}@${domain}`;
  };

  const seen = new Set<string>();
  const result: string[] = [];

  for (const email of emails) {
    const canonical = canonicalize(email);
    if (!seen.has(canonical)) {
      seen.add(canonical);
      result.push(canonical);
    }
  }

  return result;
}

