const SEMVER_RE =
  /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/

export function solve(installed: string[], range: string): string | null {
  const valid = installed.filter(
    (v) => typeof v === 'string' && SEMVER_RE.test(v.trim())
  )
  return lib.maxSatisfying(valid, range)
}

export function solve(word: string, dictionary: string[]): string {
  let best = "";
  let bestDist = Infinity;

  for (const candidate of dictionary) {
    const d = levenshtein(word, candidate);
    // Strict less-than keeps the first entry on ties.
    if (d < bestDist) {
      bestDist = d;
      best = candidate;
    }
  }

  return best;
}

function levenshtein(a: string, b: string): number {
  if (a === b) return 0;

  const m = a.length;
  const n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;

  let prev: number[] = new Array<number>(n + 1);
  let curr: number[] = new Array<number>(n + 1);

  for (let j = 0; j <= n; j++) {
    prev[j] = j;
  }

  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    const ca = a.charCodeAt(i - 1);
    for (let j = 1; j <= n; j++) {
      const cost = ca === b.charCodeAt(j - 1) ? 0 : 1;
      curr[j] = Math.min(
        prev[j] + 1,        // deletion
        curr[j - 1] + 1,    // insertion
        prev[j - 1] + cost  // substitution or match
      );
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }

  return prev[n];
}

const HOST_LABEL = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i;
const TLD = /^(?:[a-z]{2,63}|xn--[a-z0-9]+(?:-[a-z0-9]+)*)$/i;
const HTTP_PREFIX = /^https?:\/\/([^/?#]*)/i;

function hasFqdnHost(url: string): boolean {
  const match = HTTP_PREFIX.exec(url);
  if (!match) {
    return false;
  }

  // Strip optional userinfo (user:pass@).
  let authority = match[1];
  const at = authority.lastIndexOf('@');
  if (at !== -1) {
    authority = authority.slice(at + 1);
  }

  // IPv6 literals are not domain names.
  if (authority.startsWith('[')) {
    return false;
  }

  // Strip optional port.
  const colon = authority.indexOf(':');
  const host = colon === -1 ? authority : authority.slice(0, colon);

  if (host.length === 0 || host.length > 253) {
    return false;
  }

  const labels = host.split('.');
  // At least two labels is required, which rejects "localhost".
  if (labels.length < 2) {
    return false;
  }
  if (!labels.every((label) => HOST_LABEL.test(label))) {
    return false;
  }

  // The top-level domain must be alphabetic (or punycode), which rejects IPv4 addresses.
  return TLD.test(labels[labels.length - 1]);
}

export function solve(urls: string[]): string[] {
  const options = {
    protocols: ['http', 'https'],
    require_protocol: true,
    require_valid_protocol: true,
    require_tld: true,
    require_host: true,
    allow_underscores: false,
    allow_trailing_dot: false,
    allow_protocol_relative_urls: false,
    allow_fragments: true,
    allow_query_components: true,
    validate_length: true,
    max_allowed_length: 2083,
  };

  return urls.filter((url) => {
    if (typeof url !== 'string') {
      return false;
    }
    if (/\s/.test(url)) {
      return false;
    }
    if (!lib.isURL(url, options)) {
      return false;
    }
    return hasFqdnHost(url);
  });
}

export function solve(text: string): string {
    // Encode the string as UTF-8 manually (no TextEncoder, no host APIs).
    const bytes: number[] = [];
    for (const ch of text) {
        let cp = ch.codePointAt(0)!;
        // Lone surrogates have no valid UTF-8 form; substitute U+FFFD as TextEncoder does.
        if (cp >= 0xD800 && cp <= 0xDFFF) {
            cp = 0xFFFD;
        }
        if (cp < 0x80) {
            bytes.push(cp);
        } else if (cp < 0x800) {
            bytes.push(0xC0 | (cp >> 6), 0x80 | (cp & 0x3F));
        } else if (cp < 0x10000) {
            bytes.push(
                0xE0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3F),
                0x80 | (cp & 0x3F)
            );
        } else {
            bytes.push(
                0xF0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3F),
                0x80 | ((cp >> 6) & 0x3F),
                0x80 | (cp & 0x3F)
            );
        }
    }

    // Delegate the MD5 computation to the library.
    const digest = lib.md5(new Uint8Array(bytes));

    // Convert the 16-byte digest to 32 lowercase hex characters.
    let hex = "";
    for (let i = 0; i < digest.length; i++) {
        hex += (digest[i] & 0xff).toString(16).padStart(2, "0");
    }
    return hex;
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  const known = new Set<string>();
  for (const n of nodes) {
    if (known.has(n)) {
      throw new Error(`Duplicate node: ${n}`);
    }
    known.add(n);
  }

  const adj = new Map<string, string[]>();
  const indegree = new Map<string, number>();
  for (const n of nodes) {
    adj.set(n, []);
    indegree.set(n, 0);
  }

  for (const [a, b] of edges) {
    if (!known.has(a)) {
      throw new Error(`Unknown node in edge: ${a}`);
    }
    if (!known.has(b)) {
      throw new Error(`Unknown node in edge: ${b}`);
    }
    adj.get(a)!.push(b);
    indegree.set(b, indegree.get(b)! + 1);
  }

  // Kahn's algorithm; zero-indegree nodes are processed in input order.
  const queue: string[] = nodes.filter((n) => indegree.get(n) === 0);
  const result: string[] = [];

  for (let head = 0; head < queue.length; head++) {
    const n = queue[head];
    result.push(n);
    for (const m of adj.get(n)!) {
      const d = indegree.get(m)! - 1;
      indegree.set(m, d);
      if (d === 0) {
        queue.push(m);
      }
    }
  }

  if (result.length !== nodes.length) {
    throw new Error("Cycle detected in edges");
  }

  return result;
}

export function solve(stamps: string[]): number[] {
  const epochs = stamps.map((s) => {
    // Locate the date/time delimiter. Date-only strings have none.
    const delim = s.search(/[T ]/);
    let input = s;

    if (delim < 0) {
      // Date-only: anchor it to midnight UTC so it goes through the offset branch.
      input = s + "T00:00:00Z";
    } else {
      // Check whether the time portion already ends with a Z or ±hh[:mm] offset.
      const timePart = s.slice(delim + 1);
      const hasZone = /(Z|[+-]\d{2}(:?\d{2})?)$/.test(timePart);
      if (!hasZone) {
        // No offset means UTC. Appending Z forces the library's offset branch,
        // which avoids its local-time (DST-sensitive) fallback.
        input = s + "Z";
      }
    }

    const date = lib.parseISO(input);
    const ms = date.getTime();
    if (Number.isNaN(ms)) {
      throw new RangeError(`Invalid ISO 8601 date: ${JSON.stringify(s)}`);
    }
    return ms;
  });

  return epochs.sort((a, b) => a - b);
}

const BASE64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function base64Value(ch: string): number {
  return BASE64_ALPHABET.indexOf(ch);
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error("Invalid base64 input: length must be a multiple of 4");
  }

  const out: number[] = [];

  for (let i = 0; i < text.length; i += 4) {
    const isLastGroup = i + 4 === text.length;
    const c0 = text[i];
    const c1 = text[i + 1];
    const c2 = text[i + 2];
    const c3 = text[i + 3];

    const a = base64Value(c0);
    const b = base64Value(c1);
    if (a < 0 || b < 0) {
      throw new Error(`Invalid base64 character at index ${i}`);
    }

    if (c2 === "=") {
      // Only one byte encoded; must be the final group and must end with "=="
      if (!isLastGroup || c3 !== "=") {
        throw new Error(`Invalid base64 padding at index ${i}`);
      }
      const n = (a << 18) | (b << 12);
      out.push((n >> 16) & 0xff);
    } else if (c3 === "=") {
      // Two bytes encoded; must be the final group
      if (!isLastGroup) {
        throw new Error(`Invalid base64 padding at index ${i}`);
      }
      const c = base64Value(c2);
      if (c < 0) {
        throw new Error(`Invalid base64 character at index ${i + 2}`);
      }
      const n = (a << 18) | (b << 12) | (c << 6);
      out.push((n >> 16) & 0xff, (n >> 8) & 0xff);
    } else {
      // Three bytes encoded
      const c = base64Value(c2);
      const d = base64Value(c3);
      if (c < 0) {
        throw new Error(`Invalid base64 character at index ${i + 2}`);
      }
      if (d < 0) {
        throw new Error(`Invalid base64 character at index ${i + 3}`);
      }
      const n = (a << 18) | (b << 12) | (c << 6) | d;
      out.push((n >> 16) & 0xff, (n >> 8) & 0xff, n & 0xff);
    }
  }

  return out;
}

// Provided by the environment; declared here only so the module type-checks.
declare const lib: { sha1(bytes: Uint8Array): Uint8Array };

function parseUuid(uuid: string): Uint8Array {
    if (!/^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(uuid)) {
        throw new Error("Invalid namespace UUID: " + uuid);
    }
    const hex = uuid.replace(/-/g, "");
    const out = new Uint8Array(16);
    for (let i = 0; i < 16; i++) {
        out[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
    }
    return out;
}

// UTF-8 encoding of a JS string. Lone surrogates become U+FFFD,
// matching the behavior of TextEncoder.
function utf8Encode(s: string): Uint8Array {
    const out: number[] = [];
    for (let i = 0; i < s.length; i++) {
        let cp = s.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff) {
            const next = i + 1 < s.length ? s.charCodeAt(i + 1) : 0;
            if (next >= 0xdc00 && next <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
                i++;
            } else {
                cp = 0xfffd;
            }
        } else if (cp >= 0xdc00 && cp <= 0xdfff) {
            cp = 0xfffd;
        }

        if (cp < 0x80) {
            out.push(cp);
        } else if (cp < 0x800) {
            out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            out.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            out.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }
    return Uint8Array.from(out);
}

export function solve(name: string, namespace: string): string {
    const ns = parseUuid(namespace);
    const nameBytes = utf8Encode(name);

    const data = new Uint8Array(ns.length + nameBytes.length);
    data.set(ns, 0);
    data.set(nameBytes, ns.length);

    const digest = lib.sha1(data);
    const b = digest.slice(0, 16);

    // Set version (5) and RFC 4122 variant bits.
    b[6] = (b[6] & 0x0f) | 0x50;
    b[8] = (b[8] & 0x3f) | 0x80;

    const hex = Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
    return (
        hex.slice(0, 8) + "-" +
        hex.slice(8, 12) + "-" +
        hex.slice(12, 16) + "-" +
        hex.slice(16, 20) + "-" +
        hex.slice(20, 32)
    );
}

export function solve(epochMs: number): string {
  if (!Number.isFinite(epochMs)) {
    throw new RangeError("Invalid time value");
  }

  // Floor to whole milliseconds first, then to whole seconds, so that
  // negative fractional inputs round toward the earlier instant.
  const wholeMs = Math.floor(epochMs);
  const wholeSeconds = Math.floor(wholeMs / 1000);

  const d = new Date(wholeSeconds * 1000);
  if (Number.isNaN(d.getTime())) {
    throw new RangeError("Time value out of range");
  }

  const pad = (n: number, width: number): string => {
    let s = String(Math.abs(n));
    while (s.length < width) s = "0" + s;
    return s;
  };

  const year = d.getUTCFullYear();
  const yearStr =
    year >= 0 && year <= 9999
      ? pad(year, 4)
      : (year < 0 ? "-" : "+") + pad(year, 6);

  const month = pad(d.getUTCMonth() + 1, 2);
  const day = pad(d.getUTCDate(), 2);
  const hours = pad(d.getUTCHours(), 2);
  const minutes = pad(d.getUTCMinutes(), 2);
  const seconds = pad(d.getUTCSeconds(), 2);

  return `${yearStr}-${month}-${day}T${hours}:${minutes}:${seconds}Z`;
}

export function solve(a: string, b: string): boolean {
