export function solve(versions: string[]): string[] {
  const isValid = (v: string): boolean => {
    try {
      lib.compare(v, v);
      return true;
    } catch {
      return false;
    }
  };

  return versions
    .filter(isValid)
    .sort((a, b) => {
      const c = lib.compare(a, b);
      if (c !== 0) return c;
      // Equal precedence: order build metadata by full string (ASCII/code unit order)
      return a < b ? -1 : a > b ? 1 : 0;
    });
}

