export function solve(text: string): string | null {
  const runRe = /\d+/g;
  let m: RegExpExecArray | null;

  while ((m = runRe.exec(text)) !== null) {
    // A first number longer than 16 digits is not version-like; skip this run.
    if (m[0].length > 16) continue;

    const parts: string[] = [m[0]];
    let pos = m.index + m[0].length;

    // Extend with ".digits" groups, up to three numbers in total.
    while (parts.length < 3 && text[pos] === ".") {
      const numRe = /\d+/y;
      numRe.lastIndex = pos + 1;
      const n = numRe.exec(text);
      if (n === null || n[0].length > 16) break;
      parts.push(n[0]);
      pos += 1 + n[0].length;
    }

    // Leading zero in any used number of the first run: result is null.
    if (parts.some((p) => p.length > 1 && p[0] === "0")) {
      return null;
    }

    while (parts.length < 3) {
      parts.push("0");
    }
    return parts.join(".");
  }

  return null;
}

